    const svcKey = this.props.serviceState || 'operational';
    const S = s.stTick === 0 ? ({ operational: 'ok', degraded: 'degraded', unavailable: 'down' })[svcKey] : s.stState;
    const on = (v) => ({
      bd: v ? 'var(--pt-edge,rgba(79,225,222,.32))' : 'var(--pt-line,rgba(255,255,255,.085))',
      bg: v ? 'var(--pt-aquaBg,rgba(79,225,222,.12))' : 'transparent',
      col: v ? 'var(--pt-aquaTxt,#4FE1DE)' : 'var(--pt-txt2,#9FB3B8)'
    });
    const OK = { col: 'var(--pt-ok,#26C8BA)', halo: 'var(--pt-okBg,rgba(38,200,186,.14))', icon: 'check_circle', bd: 'var(--pt-line,rgba(255,255,255,.085))' };
    const WARN = { col: 'var(--pt-amber,#F0B45E)', halo: 'var(--pt-amberBg,rgba(240,180,94,.13))', icon: 'warning', bd: 'rgba(240,180,94,.28)' };
    const BAD = { col: 'var(--pt-coral,#FF7A6B)', halo: 'var(--pt-coralBg,rgba(255,122,107,.13))', icon: 'error', bd: 'rgba(255,122,107,.28)' };
    const srv = { ok: WARN, degraded: WARN, maintenance: WARN, down: BAD }[S] || WARN;
    const srvState = { ok: 'Best effort, no failover', degraded: 'Degraded — slower than usual', maintenance: 'Scheduled maintenance', down: 'Unavailable' }[S];
    return {
      cols: (isM || isT) ? '1fr' : 'minmax(0,1.15fr) minmax(0,1fr)',
      pulseStyle: 'width:8px;height:8px;border-radius:50%;background:' + (S === 'down' ? 'var(--pt-coral,#FF7A6B)' : 'var(--pt-ok,#26C8BA)') + ';animation:ptPulse 3.2s ease-in-out infinite',
      stamp: 'Checked 14:0' + (s.stTick % 10) + ' IST',
      refresh: () => this.setState({ stTick: s.stTick + 1 }),
      jumps: [['ok','Operational','check_circle'],['degraded','Degraded','warning'],['maintenance','Maintenance','build'],['down','Server unavailable','cloud_off']].map((j) => {
        const a = S === j[0]; const o = on(a);
        return { name: j[1], icon: j[2], on: a ? 'true' : 'false', bd: o.bd, bg: a ? o.bg : 'transparent', col: o.col, go: () => this.setState({ stState: j[0], stTick: s.stTick + 1 }) };
      }),
      cards: [
        { name: 'Website & local tools', state: '99.9% target · operational', note: 'All website features and every tool that runs in your browser.', c: OK },
        { name: 'Server tools (Mumbai)', state: srvState, note: 'Best-effort processing in Mumbai, India. No failover region.', c: srv },
        { name: 'Offline mode & PWA', state: 'Ready', note: 'Cached local tools keep working with no connection at all.', c: OK }
      ].map((c) => ({ name: c.name, state: c.state, note: c.note, col: c.c.col, halo: c.c.halo, icon: c.c.icon, bd: c.c.bd })),
      graceful: [
        { icon: 'block', t: 'We never fail your files. An unavailable server means the run does not start, not that a file is lost.' },
        { icon: 'devices', t: 'You can still use every local tool, including offline once the PWA is cached.' },
        { icon: 'campaign', t: 'We tell you clearly which tools are affected and why, on the tool itself.' },
        { icon: 'schedule', t: 'Try again later — no data is lost and nothing was retained in the meantime.' }
      ],
      targets: [
        { k: 'Website', v: '99.9% target' }, { k: 'Local & PWA tools', v: '99.9% target' },
        { k: 'Server tools', v: 'Best effort' }, { k: 'Failover region', v: 'None' },
        { k: 'Server location', v: 'Mumbai, India' }
      ]
    };
